import type { OutputData } from '@editorjs/editorjs'

/** Stable, opaque IDs generated by the caller, not timestamps or array indexes. */
export type ProjectId = string
export type AnnotationId = string
/** Seconds from the beginning of the recording. */
export type Seconds = number
export type NoteDocument = OutputData

export type AnnotationAnchor =
  | { kind: 'point'; time: Seconds }
  | { kind: 'range'; start: Seconds; end: Seconds }

export interface Annotation {
  id: AnnotationId
  anchor: AnnotationAnchor
  note: NoteDocument
}

/** Persisted JSON. pendingAnnotationIds is the sole source of pending status. */
export interface ProjectData {
  version: 1
  id: ProjectId
  name: string
  recording: { relativePath: string }
  annotations: Annotation[]
  projectNote: NoteDocument
  pendingAnnotationIds: AnnotationId[]
}

/** Validation requires a known duration; a range must have positive length. */
export function isValidAnchor(anchor: AnnotationAnchor, duration: Seconds): boolean {
  if (!Number.isFinite(duration) || duration < 0) return false
  const inBounds = (value: number) => Number.isFinite(value) && value >= 0 && value <= duration
  return anchor.kind === 'point'
    ? inBounds(anchor.time)
    : inBounds(anchor.start) && inBounds(anchor.end) && anchor.start < anchor.end
}

export type NoteTarget = { kind: 'project' } | { kind: 'annotation'; id: AnnotationId }
